export type ProviderError = 
/**  stop and restart discard every emulated resource and need an explicit confirmation. */
{ kind: "confirmation_required"; detail: string } | { kind: "not_configured"; detail: string } | { kind: "unsupported"; detail: string } | { kind: "tool"; detail: string } | { kind: "io"; detail: string } | { kind: "health"; detail: string };

